            out.append(stock.get(cmd[1], 0))
        elif op == "remove":
            name, q = cmd[1], cmd[2]
            cur = stock.get(name, 0)
            if cur >= q:
                stock[name] = cur - q
                out.append(True)
            else:
                out.append(False)
        elif op == "transfer":
            src, tgt, q = cmd[1], cmd[2], cmd[3]
            cur_src = stock.get(src, 0)
            if cur_src >= q:
