                reserv[name] = reserv.get(name, 0) + q
                out.append(True)
            else:
                out.append(False)
        elif op == "release":
            name, q = cmd[1], cmd[2]
            if reserv.get(name, 0) >= q:
                reserv[name] -= q
                avail[name] = avail.get(name, 0) + q
                out.append(True)
            else:
                out.append(False)
        elif op == "fulfill":
            name, q = cmd[1], cmd[2]
            if reserv.get(name, 0) >= q:
                reserv[name] -= q
                out.append(True)
            else:
                out.append(False)
        elif op == "get_reserved":
            out.append(reserv.get(cmd[1], 0))
        elif op == "begin":
            snaps.append((avail.copy(), reserv.copy()))
        elif op == "commit":
            if snaps:
                snaps.pop()
                out.append(True)
            else:
                out.append(False)
        elif op == "rollback":
            if snaps:
                avail, reserv = snaps.pop()
                out.append(True)
            else:
                out.append(False)
        elif op == "snapshot":
            out.append([[k, v] for k, v in sorted(((k, v) for k, v in avail.items() if v > 0), key=lambda x: x[0])]
                )
        else:  # "get"
            out.append(avail.get(cmd[1], 0))
    return out
